#!/usr/bin/env python3
import json,pathlib,re,hashlib
B=pathlib.Path(__file__).resolve().parent;R=B/"qa_reports"
q=[json.loads(s) for s in (R/"active_recall_v6_review"/"priority_review.jsonl").read_text().splitlines()]
done=set()
for v in ("v7","v8","v9"):
 done|={json.loads(s)["ku_id"] for s in (R/("active_recall_"+v+"_contextual")/"curated_candidates.jsonl").read_text().splitlines()}
v3={x["ku_id"]:x for x in (json.loads(s) for s in (R/"active_recall_revised_v3"/"revised_records.jsonl").read_text().splitlines())}
spec=json.loads("[[\"see\",\"see or watch\",\"From the hilltop, we could ____ the entire valley.\"],[\"state\",\"put before\",\"Please ____ your reasons clearly at the hearing.\"],[\"pay\",\"bring in\",\"The investment should ____ a modest return.\"],[\"force\",\"move with force\",\"They tried to ____ the locked door open.\"],[\"touch\",\"comprehend\",\"I cannot quite ____ the meaning of that argument.\"],[\"accord\",\"go together\",\"His actions do not ____ with his promises.\"],[\"maybe\",\"by chance\",\"____ we will meet again next summer.\"],[\"occasion\",\"give occasion to\",\"The announcement may ____ considerable debate.\"],[\"perhaps\",\"by chance\",\"____ the weather will improve tomorrow.\"],[\"correct\",\"socially right or correct\",\"It is not ____ to blame someone without evidence.\"],[\"establish\",\"institute, enact, or establish\",\"The university plans to ____ a new research center.\"],[\"do\",\"engage in\",\"We usually ____ some gardening on weekends.\"],[\"suppose\",\"expect, believe, or suppose\",\"I ____ the meeting will start at nine.\"],[\"wheel\",\"wheel somebody or something\",\"A nurse will ____ the patient into the examination room.\"],[\"abide\",\"dwell\",\"They chose to ____ in the village for several years.\"],[\"crumple\",\"fall apart\",\"The old paper began to ____ when touched.\"],[\"sour\",\"make sour or more sour\",\"Adding too much vinegar may ____ the sauce.\"],[\"rotten\",\"very bad\",\"The fruit had gone ____ after a week in the heat.\"],[\"enormously\",\"vastly\",\"The new equipment helped us ____.\"],[\"likewise\",\"in addition\",\"The first team agreed; the second team did ____.\"],[\"diminutive\",\"very small\",\"A ____ figure stood beside the much taller adults.\"],[\"hugely\",\"vastly\",\"The festival was ____ popular with local families.\"],[\"unresolved\",\"not solved\",\"Several questions remain ____ after the investigation.\"],[\"unsolved\",\"not solved\",\"The detective reopened the ____ case.\"],[\"expend\",\"pay out\",\"The company will ____ considerable resources on the project.\"],[\"coincide\",\"be the same\",\"Their holiday dates happen to ____ this year.\"],[\"blight\",\"cause to suffer a blight\",\"A prolonged drought may ____ the harvest.\"],[\"impinge\",\"impinge or infringe upon\",\"The proposed restriction could ____ on freedom of expression.\"],[\"amongst\",\"among\",\"The prize money was divided ____ the winners.\"],[\"juicy\",\"lucrative\",\"The broker hoped to secure a ____ commission.\"],[\"blend\",\"blend or harmonize\",\"The designer tried to ____ traditional and modern elements.\"],[\"quicken\",\"move faster\",\"Her pulse began to ____ as the race approached.\"],[\"counterbalance\",\"adjust for\",\"Extra weight at the rear can ____ the load at the front.\"],[\"orient\",\"be oriented\",\"The map will help you ____ yourself in the unfamiliar city.\"],[\"legitimize\",\"make legal\",\"The decree was intended to ____ the new arrangement.\"],[\"pry\",\"be nosey\",\"It would be rude to ____ into their private affairs.\"],[\"bestow\",\"present\",\"The academy will ____ its highest award on the scientist.\"],[\"disdain\",\"look down on with disdain\",\"She would never ____ a colleague for asking a simple question.\"],[\"brag\",\"show off\",\"He tends to ____ about his expensive car.\"],[\"dissimilar\",\"not similar\",\"The two approaches are quite ____ in their assumptions.\"],[\"sock\",\"hit hard\",\"In the film, the hero threatens to ____ the villain in the jaw.\"],[\"harmonize\",\"go together\",\"The new rules should ____ with existing regulations.\"],[\"escort\",\"accompany as an escort\",\"Security staff will ____ visitors to the laboratory.\"],[\"entangle\",\"entrap\",\"The fishing line could ____ a seabird.\"],[\"unproven\",\"not proved\",\"The allegation remains ____ pending further investigation.\"],[\"deceased\",\"dead\",\"The lawyer contacted the family of the ____ owner.\"],[\"maltreat\",\"treat badly\",\"The report alleged that guards had ____ prisoners.\"],[\"bide\",\"dwell\",\"He decided to ____ his time until an opportunity arose.\"],[\"bluster\",\"show off\",\"The politician continued to ____ instead of answering the question.\"],[\"speedily\",\"with speed\",\"The emergency team responded ____ to the call.\"],[\"capricious\",\"changeable\",\"The region is known for its ____ weather.\"],[\"longitudinally\",\"across time\",\"The researchers followed the participants ____ over a decade.\"],[\"mistreat\",\"treat badly\",\"No employer should ____ workers.\"],[\"earlier\",\"earlier in time; previously\",\"We met much ____ than we had planned.\"]]")
out=[]
for lemma,gloss,cloze in spec:
 m=[x for x in q if x["lemma"]==lemma and x["source_gloss_en"]==gloss and x["ku_id"] not in done]
 assert len(m)==1,(lemma,gloss,len(m))
 x=v3[m[0]["ku_id"]]
 assert cloze.count("____")==1
 assert not re.search(r"(?<![A-Za-z])"+re.escape(lemma)+r"(?![A-Za-z])",cloze,re.I)
 y=dict(x)
 y["question"]="请结合中文义项及句子语境填写英语单词（首字母："+lemma[0]+"，字母数："+str(len(lemma))+"）。\n中文义项："+x["gloss_zh"]+"\n"+cloze
 y["question_format"]="contextual_cloze_draft";y["context_example_original"]=True
 y["editorial_review_needed"]=True;y["single_answer_verified"]=False
 y["production_ready"]=False;y["release_eligible"]=False
 assert y["response"]==lemma
 out.append(y)
assert len({x["ku_id"] for x in out})==len(out)
O=R/"active_recall_v10_contextual";O.mkdir(parents=True,exist_ok=True)
p=O/"curated_candidates.jsonl"
p.write_text("".join(json.dumps(x,ensure_ascii=False)+"\n" for x in out),encoding="utf8")
summary={"new_v10_candidates":len(out),"v7_v10_total":len(done)+len(out),"remaining_without_context":135-len(done)-len(out),"editorial_review_required":True,"source_modified":False,"runtime_modified":False,"sha256":hashlib.sha256(p.read_bytes()).hexdigest()}
(O/"summary.json").write_text(json.dumps(summary,ensure_ascii=False,indent=2)+"\n")
print("V10",json.dumps(summary))
